previewCss:
.darma-loader-darma-b12-seesaw-balance { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #f59e0b); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .6); position: relative; }
.darma-loader-darma-b12-seesaw-balance::before { content: ''; position: absolute; bottom: 3%; left: 20%; width: 60%; height: 4%; border-radius: 999px; background: #cbd5e1; }
.darma-loader-darma-b12-seesaw-balance::after { content: ''; position: absolute; bottom: 6%; left: 43%; width: 14%; height: 36%; clip-path: polygon(50% 0%, 100% 100%, 0% 100%); background: var(--accent-2); }
.darma-loader-darma-b12-seesaw-balance .darma-loader-darma-b12-seesaw-balance__beam { position: absolute; bottom: 42%; left: 4%; width: 92%; height: 7%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: darma-loader-darma-b12-seesaw-balance-tilt calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; }
.darma-loader-darma-b12-seesaw-balance .darma-loader-darma-b12-seesaw-balance__beam span { position: absolute; bottom: 100%; width: calc(var(--loader-size, 112px) * .16); height: calc(var(--loader-size, 112px) * .16); border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent)); }
.darma-loader-darma-b12-seesaw-balance .darma-loader-darma-b12-seesaw-balance__beam span:nth-child(1) { left: -2%; }
.darma-loader-darma-b12-seesaw-balance .darma-loader-darma-b12-seesaw-balance__beam span:nth-child(2) { right: -2%; }
@keyframes darma-loader-darma-b12-seesaw-balance-tilt { 0%, 100% { transform: rotate(-14deg); } 50% { transform: rotate(14deg); } }

